function validateState(v){
 if(!v||v.version!==1||typeof v!=='object')throw new Error('Unrecognized progress format.');
 const out={version:1,theme:v.theme==='light'?'light':'dark',progress:{},drafts:{},quizzes:{},lastLab:lessonById(v.lastLab)?v.lastLab:null};
 for(const l of lessons){
  const p=v.progress?.[l.id];if(p&&typeof p==='object'&&p.done===true)out.progress[l.id]={done:true,at:typeof p.at==='string'?p.at.slice(0,40):'',solutionUsed:!!p.solutionUsed};
  const d=v.drafts?.[l.id];if(d&&typeof d==='object'&&typeof d.source==='string'&&d.source.length<=64000&&typeof d.input==='string'&&d.input.length<=80)out.drafts[l.id]={source:d.source,input:d.input};
  if(Number.isInteger(v.quizzes?.[l.id])&&v.quizzes[l.id]>=0&&v.quizzes[l.id]<l.quiz.options.length)out.quizzes[l.id]=v.quizzes[l.id];
 }
 return out;
}
