function trackCard(t){
 const num=t.labs.length,finished=t.labs.filter(done).length,live=liveSections[t.id];
 const pill=num?`<span class="pill ready">${num} runnable ${num===1?'lab':'labs'}</span>`:live?`<span class="pill live">Interactive</span>`:`<span class="pill planned">Planned track</span>`;
 return `<a class="track-card ${t.id==='assembly'?'featured':''}" href="#track/${t.id}"><div class="track-top"><span class="track-no">${t.n}</span>${pill}</div><h3>${t.title}</h3><p>${t.desc}</p><div class="track-bottom"><span>${num?`${finished}/${num} complete · `:live?'Interactive section · ':''}${t.units.length} curriculum units</span>${icon('arrow')}</div></a>`;
}
function drawCards(){const list=tracks.filter(t=>(filter==='All'||filter==='Runnable'&&t.labs.length||filter===t.group)&&(!query||`${t.title} ${t.desc} ${t.units.join(' ')}`.toLowerCase().includes(query.toLowerCase())));$('#track-grid').innerHTML=list.length?list.map(trackCard).join(''):'<div class="empty"><h3>No matching tracks</h3><p>Try a topic such as memory, assembly, or fuzzing.</p></div>';}
function filters(){return `<div class="filters" aria-label="Curriculum filters">${['All','Runnable','Foundation','Security','Systems','Research'].map(x=>`<button class="filter ${filter===x?'active':''}" data-filter="${x}" aria-pressed="${filter===x}">${x}</button>`).join('')}<input type="search" class="search" id="search" placeholder="Find a topic…" aria-label="Search curriculum" value="${esc(query)}"></div><div class="track-grid" id="track-grid"></div>`;}
function bindFilters(){$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;$$('[data-filter]').forEach(x=>{x.classList.toggle('active',x.dataset.filter===filter);x.setAttribute('aria-pressed',String(x.dataset.filter===filter));});drawCards();});$('#search').oninput=e=>{query=e.target.value;drawCards();};drawCards();}
