 $('#source').oninput=markDirty;$('#source').onscroll=()=>{$('#line-numbers').scrollTop=$('#source').scrollTop;};$('#source').onkeydown=e=>{if(e.key==='Tab'){e.preventDefault();const t=e.target,a=t.selectionStart,b=t.selectionEnd;t.setRangeText('    ',a,b,'end');markDirty();}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();build();}};
 $('#lab-input').oninput=markDirty;$('#build').onclick=build;$('#step').onclick=singleStep;$('#over').onclick=stepOver;$('#finish').onclick=finishFrame;$('#back').onclick=()=>{machine?.rewind();renderExecution();};$('#run').onclick=run;$('#verify').onclick=verify;
