const compiledById=id=>compiledLessons.find(l=>l.id===id);
function currentCLine(){const r=machine?.program.instructions.find(i=>BigInt(i.address)===machine.rip);return r?r.line:null;}
function stepSourceLine(over){const start=currentCLine();let budget=200000;while(budget-->0&&!['halted','fault'].includes(machine.status)){over?machine.stepOver({breakpoints}):machine.step();const l=currentCLine();if(l!==null&&l!==start)break;}}
function compiledIndex(){
 shell('compiled','Compiled C',`<div class="page-title"><div class="eyebrow">REAL COMPILER OUTPUT</div><h1>C, one layer down.</h1><p>These lessons are real C compiled with <code>gcc -O0 -g</code>. Step the source a line at a time, or drop to the exact instructions the compiler emitted for that line. The engine runs the actual bytes.</p></div><div class="lesson-list">${compiledLessons.map((l,i)=>`<a class="lesson-link" href="#clab/${l.id}"><span class="num">${String(i+1).padStart(2,'0')}</span><div><strong>${esc(l.title)}</strong><span class="meta">${esc(l.subtitle)}</span></div>${icon('arrow')}</a>`).join('')}</div><div class="notice"><strong>Two step granularities.</strong> <code>Instr</code> is one machine instruction (GDB's <code>stepi</code>). <code>Step line</code> and <code>Next line</code> advance by C source line, descending into or stepping over calls. <code>Finish</code> runs to the current function's return; <code>Back</code> reverses. These lessons are read-only; editing and rebuilding live in the assembler labs.</div>`);
}
