function drawCfgEdges(blocks,edges){
 const wrap=$('#cfg-wrap'),svg=$('#cfg-svg');if(!wrap||!svg)return;
 const W=wrap.clientWidth,H=wrap.scrollHeight,pos={};
 blocks.forEach(b=>{const el=document.getElementById('cfg-b'+b.id);if(el)pos[b.id]={top:el.offsetTop,bottom:el.offsetTop+el.offsetHeight,left:el.offsetLeft};});
 let paths='';
 edges.forEach((e,i)=>{const a=pos[e.from],b=pos[e.to];if(!a||!b)return;const lane=8+(i%4)*7,sx=a.left,tx=b.left,y0=a.bottom-4,y1=b.top+2;paths+=`<path class="cfg-path ${e.kind}${e.back?' back':''}" d="M ${sx} ${y0} C ${lane} ${y0+16}, ${lane} ${y1-16}, ${tx} ${y1}" marker-end="url(#cfg-arw)"/>`;});
 svg.setAttribute('viewBox',`0 0 ${W} ${H}`);svg.setAttribute('width',W);svg.setAttribute('height',H);
 svg.innerHTML=`<defs><marker id="cfg-arw" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M0 0 L10 5 L0 10 z"/></marker></defs>${paths}`;
}
